/**
 * @module
 * Rate Limit Middleware for Hono.
 */

import type { Context } from '../../context'
import type { MiddlewareHandler } from '../../types'

type KeyGenerator = (c: Context) => string
type SkipFunction = (c: Context) => boolean
type RateLimitHandler = (c: Context) => Response | Promise<Response>

export interface RateLimitOptions {
  limit?: number
  windowMs?: number
  keyGenerator?: KeyGenerator
  skip?: SkipFunction
  handler?: RateLimitHandler
}

const defaultKeyGenerator: KeyGenerator = (c) => {
  const forwarded = c.req.header('x-forwarded-for')
  if (forwarded) {
    return forwarded.split(',')[0].trim()
  }
  return c.req.header('x-real-ip') || 'global'
}

const defaultHandler: RateLimitHandler = () =>
  new Response(JSON.stringify({ error: 'Too Many Requests' }), {
    status: 429,
    headers: { 'content-type': 'application/json' },
  })

/**
 * Rate Limit Middleware for Hono.
 *
 * @param {RateLimitOptions} [options] - The options for the rate limit middleware.
 * @param {number} [options.limit=100] - The maximum number of requests allowed per window.
 * @param {number} [options.windowMs=60000] - The duration of the rate limit window in milliseconds.
 * @param {(c: Context) => string} [options.keyGenerator] - A function that returns the key used to identify a client. Defaults to the remote IP, read from the `X-Forwarded-For` or `X-Real-IP` request headers.
 * @param {(c: Context) => boolean} [options.skip] - A predicate that, when it returns `true`, skips rate limiting for the request.
 * @param {(c: Context) => Response | Promise<Response>} [options.handler] - A handler that produces the response returned when the limit is exceeded. Defaults to a 429 JSON response.
 * @returns {MiddlewareHandler} The middleware handler function.
 *
 * @example
 * ```ts
 * const app = new Hono()
 *
 * app.use('/api/*', rateLimit({ limit: 10, windowMs: 60_000 }))
 *
 * app.get('/api/hello', (c) => c.text('hello'))
 * ```
 */
export const rateLimit = (options?: RateLimitOptions): MiddlewareHandler => {
  const limit = options?.limit ?? 100
  const windowMs = options?.windowMs ?? 60000
  const keyGenerator = options?.keyGenerator ?? defaultKeyGenerator
  const skip = options?.skip
  const handler = options?.handler ?? defaultHandler

  const store = new Map<string, { count: number; resetAt: number }>()

  return async function rateLimit(c, next) {
    if (skip && skip(c)) {
      return next()
    }

    const key = keyGenerator(c)
    const now = Date.now()
    let entry = store.get(key)

    if (!entry || entry.resetAt <= now) {
      entry = { count: 0, resetAt: now + windowMs }
      store.set(key, entry)
    }

    entry.count++

    const resetSeconds = Math.max(0, Math.ceil((entry.resetAt - now) / 1000))

    if (entry.count > limit) {
      const response = await handler(c)
      response.headers.set('Retry-After', String(resetSeconds))
      response.headers.set('X-RateLimit-Limit', String(limit))
      response.headers.set('X-RateLimit-Remaining', '0')
      response.headers.set('X-RateLimit-Reset', String(Math.ceil(entry.resetAt / 1000)))
      return response
    }

    await next()

    const remaining = Math.max(0, limit - entry.count)
    c.res.headers.set('X-RateLimit-Limit', String(limit))
    c.res.headers.set('X-RateLimit-Remaining', String(remaining))
    c.res.headers.set('X-RateLimit-Reset', String(Math.ceil(entry.resetAt / 1000)))
  }
}

