import { Hono } from '../../hono'
import { rateLimit } from '.'

describe('Rate Limit Middleware', () => {
  let app: Hono

  beforeEach(() => {
    app = new Hono()
  })

  it('Should allow requests under the limit', async () => {
    app.use('/api/*', rateLimit({ limit: 3, windowMs: 60_000 }))
    app.get('/api/hello', (c) => c.text('hello'))

    for (let i = 0; i < 3; i++) {
      const res = await app.request('http://localhost/api/hello', {
        headers: { 'x-forwarded-for': '1.2.3.4' },
      })
      expect(res.status).toBe(200)
      expect(await res.text()).toBe('hello')
    }
  })

  it('Should set X-RateLimit-* headers on successful responses', async () => {
    app.use('/api/*', rateLimit({ limit: 5, windowMs: 60_000 }))
    app.get('/api/hello', (c) => c.text('hello'))

    const res = await app.request('http://localhost/api/hello', {
      headers: { 'x-forwarded-for': '5.6.7.8' },
    })
    expect(res.status).toBe(200)
    expect(res.headers.get('X-RateLimit-Limit')).toBe('5')
    expect(res.headers.get('X-RateLimit-Remaining')).toBe('4')
    expect(res.headers.get('X-RateLimit-Reset')).not.toBeNull()
  })

  it('Should return 429 with JSON body when limit is exceeded', async () => {
    app.use('/api/*', rateLimit({ limit: 2, windowMs: 60_000 }))
    app.get('/api/hello', (c) => c.text('hello'))

    const headers = { 'x-forwarded-for': '9.10.11.12' }
    await app.request('http://localhost/api/hello', { headers })
    await app.request('http://localhost/api/hello', { headers })
    const res = await app.request('http://localhost/api/hello', { headers })

    expect(res.status).toBe(429)
    expect(res.headers.get('content-type')).toMatch('application/json')
    expect(res.headers.get('Retry-After')).not.toBeNull()
    expect(res.headers.get('X-RateLimit-Remaining')).toBe('0')
    const body = await res.json()
    expect(body).toEqual({ error: 'Too Many Requests' })
  })

  it('Should track different clients separately', async () => {
    app.use('/api/*', rateLimit({ limit: 1, windowMs: 60_000 }))
    app.get('/api/hello', (c) => c.text('hello'))

    const res1 = await app.request('http://localhost/api/hello', {
      headers: { 'x-forwarded-for': '1.1.1.1' },
    })
    expect(res1.status).toBe(200)

    const res2 = await app.request('http://localhost/api/hello', {
      headers: { 'x-forwarded-for': '2.2.2.2' },
    })
    expect(res2.status).toBe(200)

    const res3 = await app.request('http://localhost/api/hello', {
      headers: { 'x-forwarded-for': '1.1.1.1' },
    })
    expect(res3.status).toBe(429)
  })

  it('Should reset the window after windowMs elapses', async () => {
    vi.useFakeTimers()
    app.use('/api/*', rateLimit({ limit: 1, windowMs: 1000 }))
    app.get('/api/hello', (c) => c.text('hello'))

    const headers = { 'x-forwarded-for': '3.3.3.3' }

    const first = await app.request('http://localhost/api/hello', { headers })
    expect(first.status).toBe(200)

    const second = await app.request('http://localhost/api/hello', { headers })
    expect(second.status).toBe(429)

    vi.advanceTimersByTime(1001)

    const third = await app.request('http://localhost/api/hello', { headers })
    expect(third.status).toBe(200)

    vi.useRealTimers()
  })

  it('Should use a custom keyGenerator', async () => {
    app.use(
      '/api/*',
      rateLimit({
        limit: 1,
        windowMs: 60_000,
        keyGenerator: (c) => c.req.header('x-api-key') ?? 'anonymous',
      })
    )
    app.get('/api/hello', (c) => c.text('hello'))

    const res1 = await app.request('http://localhost/api/hello', {
      headers: { 'x-api-key': 'key-a' },
    })
    expect(res1.status).toBe(200)

    const res2 = await app.request('http://localhost/api/hello', {
      headers: { 'x-api-key': 'key-b' },
    })
    expect(res2.status).toBe(200)

    const res3 = await app.request('http://localhost/api/hello', {
      headers: { 'x-api-key': 'key-a' },
    })
    expect(res3.status).toBe(429)
  })

  it('Should skip rate limiting when skip returns true', async () => {
    app.use(
      '/api/*',
      rateLimit({
        limit: 1,
        windowMs: 60_000,
        skip: (c) => c.req.header('x-bypass') === 'yes',
      })
    )
    app.get('/api/hello', (c) => c.text('hello'))

    const headers = { 'x-forwarded-for': '4.4.4.4', 'x-bypass': 'yes' }
    for (let i = 0; i < 5; i++) {
      const res = await app.request('http://localhost/api/hello', { headers })
      expect(res.status).toBe(200)
    }
  })

  it('Should use a custom handler when limit is exceeded', async () => {
    app.use(
      '/api/*',
      rateLimit({
        limit: 1,
        windowMs: 60_000,
        handler: (c) => c.text('slow down', 429),
      })
    )
    app.get('/api/hello', (c) => c.text('hello'))

    const headers = { 'x-forwarded-for': '5.5.5.5' }
    const first = await app.request('http://localhost/api/hello', { headers })
    expect(first.status).toBe(200)

    const second = await app.request('http://localhost/api/hello', { headers })
    expect(second.status).toBe(429)
    expect(await second.text()).toBe('slow down')
  })

  it('Should fall back to x-real-ip when x-forwarded-for is missing', async () => {
